/**
 * prog#572 (#647, rc23 34996503): the per-slot occupancy charge on band markets. Every row / scenario comes from the REAL
 * crate (`growth_v19::occ_*`, `state::OCC_PROFILE_BYTES`, `state::write_profile_bytes_preserving_occupancy`, rustc
 * `offset_of!`), generated by scripts/v22-parity/sdk_v22_band_parity.rs into test/fixtures/v22-band-parity.json.
 */
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import * as Band from "../src/abi/v22-band.js";
import { LAYOUT_V22 } from "../src/abi/layout.js";
import { parsePortfolioV17 } from "../src/solana/slab.js";
import { stampMarket, stampPortfolio } from "./helpers/stamp.js";

type Row = { fn: string; in: string[]; out: (string | null)[] };
type Step = { slot: string; nLong: string; nShort: string; profileOcc: string; legs: [string, boolean | null, string, string][] };
type Scenario = { name: string; cap: string; rentMax: string; minLeg: string; lpBound: boolean; fullNum: string; sides: (boolean | null)[]; steps: Step[] };
const FX = JSON.parse(readFileSync(new URL("./fixtures/v22-band-parity.json", import.meta.url), "utf8")) as {
  prog: string; occupancy: Record<string, number>; occConsts: Record<string, string>; occRows: Row[]; occScenarios: Scenario[];
};
const B = (x: string): bigint => BigInt(x);
const put = (d: Uint8Array, o: number, v: bigint, bytes = 8) => { for (let i = 0; i < bytes; i++) d[o + i] = Number((v >> BigInt(8 * i)) & 0xffn); };
const le = (v: bigint): string => { let s = ""; for (let i = 0; i < 8; i++) s += Number((v >> BigInt(8 * i)) & 0xffn).toString(16).padStart(2, "0"); return s; };

describe("prog#572 occupancy == the real crate @ 34996503", () => {
  it("fixture is from the merged program", () => {
    expect(FX.prog).toBe("34996503d21de45416bc4891b415bca83d26efbe");
  });
  it("offsets: layout row == rustc offset_of! / OCC_PROFILE_BYTES", () => {
    const O = LAYOUT_V22.bandRent!.occupancy;
    expect(O.storedPosCountLong).toBe(FX.occupancy.storedPosCountLong);
    expect(O.storedPosCountShort).toBe(FX.occupancy.storedPosCountShort);
    expect(O.slotLast).toBe(FX.occupancy.slotLast);
    expect(O.profileClockSlot).toBe(FX.occupancy.profileClockSlot);
    expect(O.profileClockLong).toBe(FX.occupancy.profileClockLong);
    expect(O.profileClockShort).toBe(FX.occupancy.profileClockShort);
    expect(O.profileClockShort + 8).toBe(FX.occupancy.profileClockEnd);
    // the clocks ARE the GH#444 fields the profile parser decodes at +408 / +416
    expect(FX.occupancy.profileCheckpointSlotField).toBe(408);
    expect(FX.occupancy.profilePreviousRateField).toBe(416);
    expect(O.vaultLpPortfolio).toBe(FX.occupancy.vaultLpPortfolio);
    expect(O.portfolioLastFeeSlot).toBe(FX.occupancy.portfolioLastFeeSlot);
  });
  it("constants", () => {
    expect(String(Band.RENT_OCC_KNEE_BPS_V22)).toBe(FX.occConsts.RENT_OCC_KNEE_BPS);
    expect(Band.RENT_OCC_CAP_DOMAIN_V22).toBe(B(FX.occConsts.RENT_OCC_CAP_DOMAIN));
    expect(Band.OCC_RAMP_ONE_V22).toBe(B(FX.occConsts.OCC_RAMP_ONE));
    expect(Band.OCC_REF_MIN_LEG_MULTIPLE_V22).toBe(B(FX.occConsts.OCC_REF_MIN_LEG_MULTIPLE));
    expect(Band.OCC_BSL_RENT_MULTIPLE_V22).toBe(B(FX.occConsts.OCC_BSL_RENT_MULTIPLE));
    expect(Band.OCC_CK_TAG_V22).toBe(B(FX.occConsts.OCC_CK_TAG));
  });
  it("pure rows: occ_ramp / occ_ramp_q32 / occ_full_num / occ_clock_advance / occ_ck_encode / occ_ck_decode / occ_charge_step", () => {
    const seen = new Map<string, number>();
    for (const r of FX.occRows) {
      const I = r.in;
      let got: (string | null)[];
      switch (r.fn) {
        case "occRamp": got = [Band.occRampV22(B(I[0]), B(I[1]), B(I[2])).toString()]; break;
        case "occRampQ32": got = [Band.occRampQ32V22(B(I[0]), B(I[1])).toString()]; break;
        case "occFullNum": got = [Band.occFullNumV22(B(I[0]), B(I[1])).toString()]; break;
        case "occClockAdvance": got = [Band.occClockAdvanceV22(B(I[0]), B(I[1]), B(I[2])).toString()]; break;
        case "occCkEncode": got = [Band.occCkEncodeV22(B(I[0]), I[1] === "true").toString()]; break;
        case "occCkDecode": { const v = Band.occCkDecodeV22(B(I[0]), I[1] === "true", B(I[2])); got = [v === null ? null : v.toString()]; break; }
        case "occChargeStep": { const v = Band.occChargeStepV22(B(I[0]), I[1] === "true", B(I[2]), B(I[3])); got = [v.checkpoint.toString(), v.due.toString()]; break; }
        default: throw new Error(`unknown fn ${r.fn}`);
      }
      expect(got, `${r.fn}(${I.join(", ")})`).toEqual(r.out);
      seen.set(r.fn, (seen.get(r.fn) ?? 0) + 1);
    }
    expect([...seen.keys()].sort()).toEqual(["occChargeStep", "occCkDecode", "occCkEncode", "occClockAdvance", "occFullNum", "occRamp", "occRampQ32"]);
    expect(FX.occRows.length).toBeGreaterThan(5000);
  });
  it("ramp shape at the seed cap: 0 through 217/256, > 0 from 218, 2^32 at 256", () => {
    expect(Band.occRampQ32V22(217n, 256n)).toBe(0n);
    expect(Band.occRampQ32V22(218n, 256n)).toBeGreaterThan(0n);
    expect(Band.occRampQ32V22(256n, 256n)).toBe(1n << 32n);
    // seed: rent_max 100, min leg $10 (1e7 atoms) -> 4 atoms per slot per leg at a full side
    expect(Band.occupancyRatesV22({ cap: 256n, fullNum: Band.occFullNumV22(100n, 10_000_000n), lpBound: true, countLong: 256n, countShort: 0n }))
      .toEqual({ long: 4_000_000_000n, short: 0n, rampQ32Long: 1n << 32n, rampQ32Short: 0n, fullE9: 4_000_000_000n });
  });
  it("scenarios: the program's clock accrual + charge (transcribed onto the real fns) and the bytes its profile writer leaves", () => {
    for (const sc of FX.occScenarios) {
      let clocks: Band.OccupancyClocksV22 = { lastSlot: 0n, longQ32: 0n, shortQ32: 0n };
      const cks = sc.sides.map(() => 0n);
      expect(Band.occFullNumV22(B(sc.rentMax), B(sc.minLeg)), sc.name).toBe(B(sc.fullNum));
      for (const st of sc.steps) {
        const p: Band.OccupancyParamsV22 = { cap: B(sc.cap), fullNum: B(sc.fullNum), lpBound: sc.lpBound, countLong: B(st.nLong), countShort: B(st.nShort) };
        sc.sides.forEach((side, i) => {
          expect(cks[i].toString(), `${sc.name}@${st.slot} leg ${i} ck in`).toBe(st.legs[i][0]);
          const r = Band.occupancyDueV22(cks[i], side === null ? null : side ? "short" : "long", clocks, p, B(st.slot));
          expect([r.checkpoint.toString(), r.due.toString()], `${sc.name}@${st.slot} leg ${i}`).toEqual([st.legs[i][2], st.legs[i][3]]);
          cks[i] = r.checkpoint;
        });
        clocks = Band.occupancyClocksAtV22(clocks, p, B(st.slot));
        expect(le(clocks.lastSlot) + le(clocks.longQ32) + le(clocks.shortQ32), `${sc.name}@${st.slot} profile bytes`).toBe(st.profileOcc);
        // and the profile parser's GH#444 view of the same bytes, reinterpreted
        const rate = clocks.longQ32 | (clocks.shortQ32 << 64n);
        expect(Band.occupancyClocksFromProfileV22({ maintenanceFeeCheckpointSlot: clocks.lastSlot, maintenanceFeePreviousRate: rate })).toEqual(clocks);
      }
    }
    expect(FX.occScenarios.map((s) => s.name)).toEqual(["knee_then_full", "small_cap_rounding", "no_lp_frozen", "rent_off", "slot_not_forward"]);
  });
  it("NEGATIVE CONTROL: a floored ramp, or a checkpoint that drops the sub-atom carry, would not match", () => {
    const floorRamp = (c: bigint, cap: bigint, max: bigint) => { const r = Band.occRampV22(c, cap, max); return r > 1n && r < max ? r - 1n : r; };
    expect(FX.occRows.some((r) => r.fn === "occRamp" && floorRamp(B(r.in[0]), B(r.in[1]), B(r.in[2])).toString() !== r.out[0])).toBe(true);
    const noCarry = (ck: bigint, short: boolean, c: bigint, f: bigint) => { const s = Band.occChargeStepV22(ck, short, c, f); return s.due === 0n ? Band.occCkEncodeV22(c >> 32n, short) : s.checkpoint; };
    expect(FX.occRows.some((r) => r.fn === "occChargeStep" && noCarry(B(r.in[0]), r.in[1] === "true", B(r.in[2]), B(r.in[3])).toString() !== r.out[0])).toBe(true);
  });
});

function bandMarket(o: { band?: number; rentMax?: bigint; minLeg?: bigint; cap?: bigint; nLong?: bigint; nShort?: bigint; bound?: boolean; mode?: number; clocks?: [bigint, bigint, bigint] }): Uint8Array {
  const L = LAYOUT_V22, R = L.bandRent!, O = R.occupancy;
  const d = stampMarket(new Uint8Array(L.marketGroupOff + L.marketGroupLen + L.assetSlotStride), 19);
  const cfg = L.marketGroupOff + L.group.config;
  put(d, cfg + R.config.bandBps, BigInt(o.band ?? 130)); put(d, cfg + R.config.rentMaxE9PerSlot, o.rentMax ?? 100n);
  put(d, cfg + R.config.bandMaxPositionsPerSide, o.cap ?? 256n); put(d, cfg + R.config.bandMinLegNotional, o.minLeg ?? 10_000_000n);
  d[L.marketGroupOff + L.group.mode] = o.mode ?? 0;
  const s = L.marketGroupOff + L.marketGroupLen, e = s + L.wrapperSlotLen;
  put(d, e + O.storedPosCountLong, o.nLong ?? 0n); put(d, e + O.storedPosCountShort, o.nShort ?? 0n);
  d[s + L.wrapperSlot.vaultLp + R.vaultLp.flags] = o.bound === false ? 0 : 1;
  const [ls, cl, cs] = o.clocks ?? [0n, 0n, 0n];
  const p = s + L.wrapperSlot.oracleProfile;
  put(d, p + O.profileClockSlot, ls); put(d, p + O.profileClockLong, cl); put(d, p + O.profileClockShort, cs);
  return d;
}

describe("prog#572 decoders and the view", () => {
  it("decodeOccupancyStateV22 reads the counts, clocks and binding; null without a band", () => {
    const d = bandMarket({ nLong: 240n, nShort: 256n, clocks: [77n, 5n << 32n, (9n << 32n) + 1n] });
    const occ = Band.decodeOccupancyStateV22(d)!;
    expect(occ).toMatchObject({ enabled: true, live: true, clocks: { lastSlot: 77n, longQ32: 5n << 32n, shortQ32: (9n << 32n) + 1n } });
    expect(occ.params).toEqual({ cap: 256n, fullNum: 4_000_000_000n, lpBound: true, countLong: 240n, countShort: 256n });
    expect(Band.decodeOccupancyStateV22(bandMarket({ band: 0 }))).toBeNull();
    expect(Band.decodeOccupancyStateV22(bandMarket({ mode: 1 }))!.enabled).toBe(false);
    expect(Band.decodeOccupancyStateV22(bandMarket({ bound: false }))!.enabled).toBe(false);
    expect(Band.decodeOccupancyStateV22(bandMarket({ rentMax: 0n }))!.enabled).toBe(false);
  });
  it("occupancyRatesFromStateV22 + the band view: utilisation rent unchanged, occupancy separate, 0 at the knee", () => {
    const v = Band.readBandRentViewV22(bandMarket({ nLong: 217n, nShort: 256n }))!;
    expect(v.occupancy).toMatchObject({ enabled: true, cap: 256n, countLong: 217n, countShort: 256n, long: 0n, short: 4_000_000_000n, fullE9: 4_000_000_000n });
    expect(v.rentRates).toEqual({ enabled: true, long: 0n, short: 0n }); // no measured N_cap here: util rent 0, occupancy still charged
    expect(Band.occupancyRatesFromStateV22(null).long).toBe(0n);
    expect(Band.occupancyRatesFromStateV22(Band.decodeOccupancyStateV22(bandMarket({ nLong: 256n, mode: 1 }))).long).toBe(0n);
    expect(Band.readBandRentViewV22(bandMarket({ nLong: 256n }), 0)!.occupancy!.long).toBe(4_000_000_000n);
  });
  it("occupancyDueV22: the vault LP never pays, a flat portfolio drops a tagged word, a foreign word re-anchors", () => {
    const p: Band.OccupancyParamsV22 = { cap: 256n, fullNum: 4_000_000_000n, lpBound: true, countLong: 256n, countShort: 256n };
    const clocks = { lastSlot: 100n, longQ32: 0n, shortQ32: 0n };
    const ck = Band.occCkEncodeV22(0n, false);
    expect(Band.occupancyDueV22(ck, "long", clocks, p, 110n)).toEqual({ checkpoint: Band.occCkEncodeV22(10n, false), due: 40n });
    expect(Band.occupancyDueV22(ck, "long", clocks, p, 110n, true)).toEqual({ checkpoint: Band.occCkEncodeV22(10n, false), due: 0n });
    expect(Band.occupancyDueV22(ck, null, clocks, p, 110n)).toEqual({ checkpoint: 0n, due: 0n });
    expect(Band.occupancyDueV22(12_345n, "long", clocks, p, 110n)).toEqual({ checkpoint: Band.occCkEncodeV22(10n, false), due: 0n });
    expect(Band.occupancyDueV22(ck, "short", clocks, p, 110n).due).toBe(0n); // other side's word: re-anchor
    // no bound LP: nothing owed, and the program RE-ANCHORS at the (frozen) clock rather than keeping an older checkpoint
    const later = { lastSlot: 100n, longQ32: 10n << 32n, shortQ32: 0n };
    expect(Band.occupancyDueV22(Band.occCkEncodeV22(3n, false), "long", later, { ...p, lpBound: false }, 200n)).toEqual({ checkpoint: Band.occCkEncodeV22(10n, false), due: 0n });
    expect(Band.occupancyDueV22(Band.occCkEncodeV22(3n, false), "long", later, { ...p, fullNum: 0n }, 200n)).toEqual({ checkpoint: Band.occCkEncodeV22(10n, false), due: 0n });
  });
  it("parsePortfolioV17: lastFeeSlot is decoded as a tagged checkpoint at the crate's offset; a real slot is not", () => {
    const L = LAYOUT_V22;
    const d = stampPortfolio(new Uint8Array(L.portfolio.accountLen), 19);
    const at = 16 + L.bandRent!.occupancy.portfolioLastFeeSlot; // account = 16-byte header + PortfolioAccountV16Account
    put(d, at, Band.occCkEncodeV22(1234n, true));
    const pf = parsePortfolioV17(d);
    expect(pf.lastFeeSlot).toBe(Band.occCkEncodeV22(1234n, true));
    expect(pf.occupancyCheckpoint).toEqual({ short: true, clockInt: 1234n });
    expect(Band.decodeOccupancyCheckpointV22(pf.lastFeeSlot)).toEqual(pf.occupancyCheckpoint);
    put(d, at, 312_000_000n);
    expect(parsePortfolioV17(d).occupancyCheckpoint).toBeNull();
    expect(Band.decodeOccupancyCheckpointV22(312_000_000n)).toBeNull();
  });
});
